import React, { useEffect } from 'react';
import { App } from '@capacitor/app';
import { supabase } from '../config/supabase';

/**
 * MobileAppManager
 * Headless component that handles native lifecycle events like backgrounding,
 * deep linking, and cloud sync resilience for mobile devices.
 */
const MobileAppManager = () => {
    useEffect(() => {
        // Only run if Capacitor is actually available (won't crash on web)
        let appStateListener;
        
        const initNativeListeners = async () => {
            try {
                appStateListener = await App.addListener('appStateChange', async ({ isActive }) => {
                    console.log('📱 Native App State changed. Is active?', isActive);
                    
                    if (!isActive) {
                        // The user just swiped out of the app or got a phone call.
                        // We must immediately trigger a cloud sync of their local data.
                        console.log('⏸️ App Backgrounded. Forcing immediate cloud sync...');
                        
                        try {
                            // Extract current local storage stats
                            const userId = localStorage.getItem('guest_user_id');
                            if (userId && window.supabase) {
                                const payload = {
                                    id: userId,
                                    credits: parseInt(localStorage.getItem('credits')) || 1000,
                                    gems: parseInt(localStorage.getItem('playerGems')) || 0,
                                    inventory: JSON.parse(localStorage.getItem('playerInventory')) || [],
                                    stats: JSON.parse(localStorage.getItem('playerStats')) || {},
                                    unlocked_ships: JSON.parse(localStorage.getItem('unlockedShips')) || [],
                                    last_sync: new Date().toISOString()
                                };
                                
                                // Perform sync
                                await supabase.from('profiles').upsert(payload);
                                console.log('✅ Background Cloud Sync Complete.');
                            }
                        } catch (e) {
                            console.error('❌ Background Sync Failed:', e);
                        }
                    } else {
                        console.log('▶️ App Resumed. Game loops can continue.');
                    }
                });
            } catch (e) {
                console.log("Not running in native Capacitor context. Skipping native background listeners.");
            }
        };

        initNativeListeners();

        return () => {
            if (appStateListener) {
                appStateListener.remove();
            }
        };
    }, []);

    // This component renders nothing, it purely manages side-effects and native APIs
    return null;
};

export default MobileAppManager;
